  handDrag($('osv'),[630,280],[100,105,700,235],pt=>{const was=RL.str.some(a=>a>2);RL.str=RL.str.map(()=>.01);rlSilence();bigHandAt(pt.x,172);$('rmsg').innerHTML=was?`✋ You pressed the strings! No vibration → no sound. ${AR('ضَغَطْتَ عَلَى الْأَوْتَارِ! لَا اهْتِزَازَ ← لَا صَوْتَ.')}`:`The strings are still. Pluck them first! ${AR('الْأَوْتَارُ سَاكِنَةٌ. انْقُرْهَا أَوَّلًا!')}`;if(was)rlEvent('ostop')});
