/* give the hands-on labs a music-room background (drawn behind everything, kept when the lab redraws its parts) */
['lab','ruler','safe'].forEach(k=>{const f=ACTS[k];ACTS[k]=id=>{f(id);const paintBG=()=>{const sv=[...document.querySelectorAll('#act svg')].find(v=>v.viewBox&&v.viewBox.baseVal&&v.viewBox.baseVal.width>=500);if(!sv||sv.querySelector(':scope>.roombg'))return;const vb=sv.viewBox.baseVal;sv.insertAdjacentHTML('afterbegin',`<g class="roombg" pointer-events="none">${roomBG(vb.width,vb.height+vb.y,(vb.height+vb.y)*.86)}</g>`)};paintBG();const mo=new MutationObserver(paintBG);mo.observe($('act'),{childList:true,subtree:true});const tk=actTok;const iv=setInterval(()=>{if(tk!==actTok){mo.disconnect();clearInterval(iv)}},1000)}});
